sp_widget.client_script:
api.controller = function($scope, $window) {
    var c = this;

    c.activeFilter = "all";
    c.workingId = null;
    c.feedback = c.data.feedback || "";
    c.feedbackType = c.data.feedbackType || "success";

    // Pagination
    c.pageSize = 6;
    c.currentPage = 1;

    c.filters = [
        { label: "All", value: "all" },
        { label: "Active", value: "active" },
        { label: "Due soon", value: "due" },
        { label: "Returned", value: "returned" }
    ];

    c.setFilter = function(value) {
        c.activeFilter = value;
        c.currentPage = 1;
    };

    c.visibleRentals = function() {
        var rentals = c.data.rentals || [];

        return rentals.filter(function(rental) {
            if (c.activeFilter === "all") return true;

            if (c.activeFilter === "active") {
                return rental.statusClass === "active" ||
                    rental.statusClass === "due" ||
                    rental.statusClass === "overdue";
            }

            if (c.activeFilter === "due") {
                return rental.statusClass === "due" ||
                    rental.statusClass === "overdue";
            }

            if (c.activeFilter === "returned") {
                return rental.statusClass === "returned";
            }

            return true;
        });
    };

    c.countFor = function(filter) {
        var previous = c.activeFilter;
        c.activeFilter = filter;
        var count = c.visibleRentals().length;
        c.activeFilter = previous;
        return count;
    };

    c.totalPages = function() {
        return Math.max(
            1,
            Math.ceil(c.visibleRentals().length / c.pageSize)
        );
    };

    c.pageRentals = function() {
        var rentals = c.visibleRentals();
        var start = (c.currentPage - 1) * c.pageSize;

        return rentals.slice(start, start + c.pageSize);
    };

    c.startRecord = function() {
        return c.visibleRentals().length
            ? (c.currentPage - 1) * c.pageSize + 1
            : 0;
    };

    c.endRecord = function() {
        return Math.min(
            c.currentPage * c.pageSize,
            c.visibleRentals().length
        );
    };

    c.previousPage = function() {
        if (c.currentPage > 1) c.currentPage--;
    };

    c.nextPage = function() {
        if (c.currentPage < c.totalPages()) c.currentPage++;
    };

    c.confirmAction = function(rental, action) {
        if (c.workingId) return;

        var message = action === "return"
            ? "Submit the return for " + rental.assetName + "?"
            : "Submit a renewal request for " + rental.assetName + "?";

        if (!$window.confirm(message)) return;

        c.workingId = rental.id;
        c.feedback = "";

        c.server.get({
            action: action,
            rentalId: rental.id
        }).then(function(response) {
            c.data = response.data;
            c.feedback = response.data.feedback || "Your request has been processed.";
            c.feedbackType = response.data.feedbackType || "success";

            // Keep the current page valid after the data refresh.
            if (c.currentPage > c.totalPages()) {
                c.currentPage = c.totalPages();
            }
        }, function() {
            c.feedback = "We couldn't process your request. Please try again.";
            c.feedbackType = "error";
        }).finally(function() {
            c.workingId = null;
        });
    };
};

sp_widget.css:
/* =========================================
   CAMPUSOPS — MY RENTALS
========================================= */

.co-rentals-app {
  --cr-ink:#34264f;
  --cr-muted:#887d99;
  --cr-purple:#8062c9;
  --cr-border:#e9e1f3;
  width:100%;
  color:var(--cr-ink);
  font-family:Inter,"Segoe UI",Arial,sans-serif;
  font-size:13px;
  line-height:1.55;
}

.co-rentals-app * { box-sizing:border-box; }
.co-rentals-app a { text-decoration:none; }
.co-rentals-app button { font:inherit; }
.co-rentals-app a:focus-visible,
.co-rentals-app button:focus-visible {
  outline:2px solid #8062c9;
  outline-offset:3px;
}

/* LAYOUT */

.co-rentals-app .cr-layout {
  display:grid;
  grid-template-columns:218px minmax(0,1fr);
  align-items:stretch;
  gap:25px;
  width:100%;
}

.co-rentals-app .cr-sidebar {
  display:flex;
  flex-direction:column;
  min-width:0;
  min-height:690px;
  padding:20px 13px;
  border:1px solid #e9e0f5;
  border-radius:19px;
  background:linear-gradient(180deg,#f8f4ff,#f3effb);
}

.co-rentals-app .cr-brand {
  display:flex;
  align-items:center;
  gap:10px;
  padding:4px 7px 24px;
  color:#382b54;
}

.co-rentals-app .cr-brand-mark {
  display:grid;
  place-items:center;
  flex-shrink:0;
  width:37px;
  height:37px;
  border-radius:11px;
  background:#8062c9;
  color:#fff;
  font-size:19px;
  font-weight:800;
}

.co-rentals-app .cr-brand b {
  display:block;
  font-size:14px;
  line-height:1.2;
}

.co-rentals-app .cr-brand small {
  display:block;
  margin-top:4px;
  color:#8b7e9e;
  font-size:9px;
  font-weight:500;
}

.co-rentals-app .cr-nav-label {
  padding:9px 10px;
  color:#a092b6;
  font-size:9px;
  font-weight:800;
  letter-spacing:1.1px;
}

.co-rentals-app .cr-nav-spaced { margin-top:18px; }

.co-rentals-app .cr-nav {
  display:flex;
  align-items:center;
  gap:11px;
  margin:2px 0;
  padding:11px 10px;
  border-radius:10px;
  color:#6e6382;
  font-size:11px;
  font-weight:600;
  transition:background .18s,color .18s;
}

.co-rentals-app .cr-nav > span {
  display:grid;
  place-items:center;
  width:21px;
  flex-shrink:0;
  color:#8d79b5;
  font-size:16px;
}

.co-rentals-app .cr-nav:hover {
  background:rgba(255,255,255,.8);
  color:#513a83;
}

.co-rentals-app .cr-nav-active {
  background:#e8defa;
  color:#6245a0;
  font-weight:750;
}

.co-rentals-app .cr-nav-active > span { color:#7354b4; }

.co-rentals-app .cr-sidebar-bottom {
  display:flex;
  flex-direction:column;
  gap:4px;
  margin-top:auto;
  padding:18px 8px 3px;
  border-top:1px solid #e4dbef;
}

.co-rentals-app .cr-sidebar-bottom span {
  color:#59446f;
  font-size:10px;
  font-weight:750;
}

.co-rentals-app .cr-sidebar-bottom small {
  color:#9386a5;
  font-size:9px;
}

/* PAGE HEADER */

.co-rentals-app .cr-main { min-width:0; }

.co-rentals-app .cr-header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  margin:4px 0 23px;
}

.co-rentals-app .cr-eyebrow {
  color:#927bb7;
  font-size:9px;
  font-weight:800;
  letter-spacing:1.2px;
}

.co-rentals-app .cr-header h1 {
  margin:9px 0 5px;
  color:#34264f;
  font-size:clamp(25px,2.6vw,33px);
  font-weight:800;
  letter-spacing:-.8px;
  line-height:1.25;
}

.co-rentals-app .cr-header p {
  margin:0;
  color:#897d99;
  font-size:11px;
}

.co-rentals-app .cr-browse-link {
  flex-shrink:0;
  padding:9px 12px;
  border:1px solid #e8def4;
  border-radius:10px;
  background:rgba(255,255,255,.8);
  color:#7356ad;
  font-size:10px;
  font-weight:750;
}

.co-rentals-app .cr-browse-link:hover { background:#fff; }

/* ACTION FEEDBACK */

.co-rentals-app .cr-feedback {
  margin-bottom:17px;
  padding:12px 14px;
  border:1px solid #ccebd8;
  border-radius:11px;
  background:#f0faf4;
  color:#397b58;
  font-size:11px;
}

.co-rentals-app .cr-feedback-error {
  border-color:#f0d1d9;
  background:#fff5f7;
  color:#ae4964;
}

/* OVERVIEW */

.co-rentals-app .cr-overview {
  margin-bottom:23px;
  padding:18px;
  border:1px solid var(--cr-border);
  border-radius:15px;
  background:rgba(255,255,255,.84);
  box-shadow:0 5px 18px rgba(79,60,118,.035);
}

.co-rentals-app .cr-overview-heading h2,
.co-rentals-app .cr-collection-heading h2 {
  margin:0;
  color:#403254;
  font-size:15px;
  font-weight:800;
}

.co-rentals-app .cr-overview-heading p,
.co-rentals-app .cr-collection-heading p {
  margin:4px 0 0;
  color:#8c809b;
  font-size:10px;
}

.co-rentals-app .cr-stats {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  margin-top:17px;
}

.co-rentals-app .cr-stat {
  display:flex;
  flex-direction:column;
  gap:5px;
  padding:4px 13px;
  border-left:1px solid #eee7f6;
}

.co-rentals-app .cr-stat:first-child {
  padding-left:0;
  border-left:0;
}

.co-rentals-app .cr-stat span {
  color:#887b98;
  font-size:10px;
}

.co-rentals-app .cr-stat strong {
  color:#403052;
  font-size:23px;
  font-weight:800;
  line-height:1.2;
}

.co-rentals-app .cr-stat .cr-alert-number { color:#b95170; }

/* COLLECTION */

.co-rentals-app .cr-collection { margin-bottom:23px; }

.co-rentals-app .cr-collection-heading { margin-bottom:13px; }

.co-rentals-app .cr-filters {
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin-bottom:15px;
}

.co-rentals-app .cr-filters button {
  display:inline-flex;
  align-items:center;
  gap:7px;
  padding:7px 10px;
  border:1px solid #e9e1f3;
  border-radius:9px;
  background:#fff;
  color:#776a8b;
  cursor:pointer;
  font-size:10px;
  transition:background .15s,border-color .15s;
}

.co-rentals-app .cr-filters button span {
  color:#9a8eaa;
  font-size:9px;
}

.co-rentals-app .cr-filters button:hover {
  border-color:#cfc0eb;
  background:#faf7ff;
}

.co-rentals-app .cr-filters button.cr-filter-active {
  border-color:#8062c9;
  background:#8062c9;
  color:#fff;
}

.co-rentals-app .cr-filters button.cr-filter-active span { color:#eee5ff; }

/* RENTAL CARDS */

.co-rentals-app .cr-rental-grid {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:12px;
}

.co-rentals-app .cr-rental-card {
  display:flex;
  flex-direction:column;
  min-width:0;
  padding:15px;
  border:1px solid #e7def4;
  border-radius:14px;
  background:rgba(255,255,255,.87);
  box-shadow:0 4px 13px rgba(79,60,118,.025);
  transition:transform .18s,border-color .18s,box-shadow .18s;
}

.co-rentals-app .cr-rental-card:hover {
  transform:translateY(-2px);
  border-color:#d4c4ee;
  box-shadow:0 8px 20px rgba(79,60,118,.07);
}

.co-rentals-app .cr-card-top {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-bottom:12px;
}

.co-rentals-app .cr-resource-mark {
  display:grid;
  place-items:center;
  width:33px;
  height:33px;
  flex-shrink:0;
  border-radius:10px;
  background:#eee7fc;
  color:#7859b7;
  font-size:17px;
}

.co-rentals-app .cr-resource-book { background:#eee7fc;color:#7859b7; }
.co-rentals-app .cr-resource-laptop { background:#e9f2ff;color:#547eaf; }
.co-rentals-app .cr-resource-kit { background:#fff0e3;color:#bd8248; }
.co-rentals-app .cr-resource-other { background:#e8f7f1;color:#519b82; }

.co-rentals-app .cr-status {
  display:inline-block;
  padding:4px 8px;
  border-radius:20px;
  font-size:9px;
  font-weight:750;
  white-space:nowrap;
}

.co-rentals-app .cr-status-active { background:#eaf7ef;color:#4c956f; }
.co-rentals-app .cr-status-due { background:#fff3dc;color:#a8762d; }
.co-rentals-app .cr-status-overdue { background:#fce8ed;color:#b34e6b; }
.co-rentals-app .cr-status-returned { background:#f0e9ff;color:#8060b8; }

.co-rentals-app .cr-resource-type {
  margin-bottom:3px;
  color:#9588a6;
  font-size:9px;
  text-transform:uppercase;
  letter-spacing:.5px;
}

.co-rentals-app .cr-rental-card h3 {
  margin:0;
  color:#44345d;
  font-size:12px;
  font-weight:800;
  overflow-wrap:anywhere;
}

.co-rentals-app .cr-location {
  margin-top:4px;
  color:#9386a4;
  font-size:9px;
}

/* DUE DATE */

.co-rentals-app .cr-deadline {
  display:flex;
  flex-direction:column;
  gap:4px;
  margin-top:13px;
  padding:10px 11px;
  border:1px solid #e4d9f6;
  border-radius:10px;
  background:#f8f4ff;
}

.co-rentals-app .cr-deadline-label {
  color:#8977aa;
  font-size:8px;
  font-weight:800;
  letter-spacing:.65px;
}

.co-rentals-app .cr-deadline strong {
  color:#55416f;
  font-size:10px;
}

.co-rentals-app .cr-deadline-soon {
  border-color:#f3dfb7;
  background:#fff9ed;
}

.co-rentals-app .cr-deadline-soon .cr-deadline-label,
.co-rentals-app .cr-deadline-soon strong { color:#a8762d; }

.co-rentals-app .cr-deadline-overdue {
  border-color:#f1d1da;
  background:#fff5f7;
}

.co-rentals-app .cr-deadline-overdue .cr-deadline-label,
.co-rentals-app .cr-deadline-overdue strong { color:#b34e6b; }

.co-rentals-app .cr-deadline-returned {
  border-color:#ccebd8;
  background:#f0faf4;
}

.co-rentals-app .cr-deadline-returned .cr-deadline-label,
.co-rentals-app .cr-deadline-returned strong { color:#478766; }

/* DETAILS */

.co-rentals-app .cr-record-details {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
  margin-top:12px;
  padding-bottom:12px;
  border-bottom:1px solid #f0ebf6;
}

.co-rentals-app .cr-record-details div {
  display:flex;
  flex-direction:column;
  gap:3px;
  min-width:0;
}

.co-rentals-app .cr-record-details small {
  color:#9589a5;
  font-size:9px;
}

.co-rentals-app .cr-record-details strong {
  color:#665776;
  font-size:9px;
  overflow-wrap:anywhere;
}

.co-rentals-app .cr-renewal-note {
  margin-top:10px;
  padding:9px;
  border-radius:8px;
  background:#f4efff;
  color:#7054a5;
  font-size:9px;
}

.co-rentals-app .cr-card-actions {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:7px;
  margin-top:auto;
  padding-top:12px;
}

.co-rentals-app .cr-card-actions button {
  min-width:0;
  min-height:32px;
  padding:7px 8px;
  border:1px solid #8062c9;
  border-radius:8px;
  cursor:pointer;
  font-size:9px;
  font-weight:750;
  transition:background .15s,opacity .15s;
}

.co-rentals-app .cr-return-button {
  background:#8062c9;
  color:#fff;
}

.co-rentals-app .cr-return-button:hover { background:#6f50b5; }

.co-rentals-app .cr-renew-button {
  background:#fff;
  color:#7455b3;
}

.co-rentals-app .cr-renew-button:hover { background:#f7f2ff; }

.co-rentals-app .cr-card-actions button:disabled {
  opacity:.55;
  cursor:not-allowed;
}

.co-rentals-app .cr-returned-note {
  margin-top:auto;
  padding-top:13px;
  color:#478766;
  font-size:10px;
}

/* LOADING AND EMPTY STATES */

.co-rentals-app .cr-loading,
.co-rentals-app .cr-empty {
  padding:26px 15px;
  border:1px dashed #e4d8f1;
  border-radius:13px;
  background:#fcfaff;
  text-align:center;
}

.co-rentals-app .cr-loading {
  color:#796b8d;
  font-size:11px;
}

.co-rentals-app .cr-empty h3 {
  margin:0;
  color:#49385f;
  font-size:13px;
}

.co-rentals-app .cr-empty p {
  margin:6px 0 12px;
  color:#887b98;
  font-size:10px;
}

.co-rentals-app .cr-empty a,
.co-rentals-app .cr-empty button {
  display:inline-block;
  padding:8px 11px;
  border:1px solid #dfd2f2;
  border-radius:8px;
  background:#fff;
  color:#7959b8;
  font-size:10px;
  font-weight:750;
  cursor:pointer;
}

/* HELP */

.co-rentals-app .cr-help {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:15px;
  border:1px solid #e8e0f1;
  border-radius:13px;
  background:#faf7ff;
}

.co-rentals-app .cr-help strong {
  color:#49385f;
  font-size:11px;
}

.co-rentals-app .cr-help p {
  margin:4px 0 0;
  color:#887b98;
  font-size:10px;
}

.co-rentals-app .cr-help > a {
  flex-shrink:0;
  color:#7959b8;
  font-size:10px;
  font-weight:750;
}

/* FOOTER */

.co-rentals-app .cr-footer {
  margin-top:26px;
  padding:17px 2px 5px;
  border-top:1px solid #e9e2f1;
}

.co-rentals-app .cr-footer-top {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.co-rentals-app .cr-footer-top strong {
  color:#55416f;
  font-size:11px;
}

.co-rentals-app .cr-footer-top span {
  color:#988ca8;
  font-size:9px;
}

.co-rentals-app .cr-footer-links {
  display:flex;
  flex-wrap:wrap;
  gap:16px;
  margin-top:12px;
}

.co-rentals-app .cr-footer-links a {
  color:#796a8d;
  font-size:10px;
}

.co-rentals-app .cr-footer-links a:hover { color:#6748a8; }

.co-rentals-app .cr-footer-copy {
  margin-top:12px;
  color:#a399b1;
  font-size:9px;
}

/* RESPONSIVE */

@media(max-width:900px) {
  .co-rentals-app .cr-layout {
    grid-template-columns:175px minmax(0,1fr);
    gap:16px;
  }

  .co-rentals-app .cr-sidebar { padding:15px 9px; }
  .co-rentals-app .cr-nav { gap:8px;padding:10px 8px; }
}

@media(max-width:680px) {
  .co-rentals-app .cr-layout { grid-template-columns:1fr;gap:18px; }

  .co-rentals-app .cr-sidebar {
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    align-content:start;
    gap:3px;
    min-height:0;
    padding:12px;
  }

  .co-rentals-app .cr-brand {
    grid-column:1/-1;
    padding-bottom:12px;
  }

  .co-rentals-app .cr-nav-label,
  .co-rentals-app .cr-sidebar-bottom { display:none; }

  .co-rentals-app .cr-nav { margin:0; }

  .co-rentals-app .cr-header h1 { font-size:25px; }
  .co-rentals-app .cr-browse-link { display:none; }

  .co-rentals-app .cr-rental-grid { grid-template-columns:1fr; }
  .co-rentals-app .cr-help { align-items:flex-start;flex-direction:column; }
  .co-rentals-app .cr-footer-top { align-items:flex-start;flex-direction:column; }
}

@media(max-width:400px) {
  .co-rentals-app .cr-stats { grid-template-columns:1fr;gap:9px; }

  .co-rentals-app .cr-stat {
    flex-direction:row;
    justify-content:space-between;
    align-items:center;
    padding:7px 0;
    border-left:0;
    border-bottom:1px solid #eee7f6;
  }

  .co-rentals-app .cr-stat:last-child { border-bottom:0; }
}


/* RENTAL PAGINATION */

.co-rentals-app .cr-pagination {
  display:flex;
  align-items:center;
  justify-content:space-between;
  flex-wrap:wrap;
  gap:12px;
  margin-top:16px;
  padding:12px 0;
}

.co-rentals-app .cr-page-info {
  color:#887b98;
  font-size:10px;
}

.co-rentals-app .cr-page-controls {
  display:flex;
  align-items:center;
  gap:8px;
}

.co-rentals-app .cr-page-controls button {
  padding:8px 11px;
  border:1px solid #e5dcf2;
  border-radius:8px;
  background:#fff;
  color:#7255ad;
  font-size:10px;
  font-weight:700;
  cursor:pointer;
}

.co-rentals-app .cr-page-controls button:hover:not(:disabled) {
  background:#f5efff;
  border-color:#cfc0eb;
}

.co-rentals-app .cr-page-controls button:disabled {
  opacity:.4;
  cursor:not-allowed;
}

.co-rentals-app .cr-page-number {
  min-width:42px;
  color:#665575;
  font-size:10px;
  text-align:center;
}

sp_widget.script:
(function() {
    data.loading = true;
    data.rentals = [];
    data.activeCount = 0;
    data.attentionCount = 0;
    data.feedback = "";
    data.feedbackType = "success";

    var userId = gs.getUserID();

    // Handle an action requested by the widget.
    if (input && input.action && input.rentalId) {
        var target = new GlideRecord("u_student_rental");
        target.addQuery("sys_id", input.rentalId);
        target.addQuery("u_student", userId);
        target.addQuery("u_status", "active");
        target.setLimit(1);
        target.query();

        if (!target.next()) {
            data.feedback = "This active rental could not be found for your account. Refresh the page and try again.";
            data.feedbackType = "error";
        } else if (input.action === "return") {
            target.setValue("u_status", "returned");
            target.update();

            data.feedback = "Return submitted successfully. Your return workflow has been triggered.";
            data.feedbackType = "success";

        } else if (input.action === "renew") {
            if (target.getValue("u_renewal_requested") == "true") {
                data.feedback = "A renewal request is already pending for this rental.";
                data.feedbackType = "error";
            } else {
                target.setValue("u_renewal_requested", true);
                target.update();

                data.feedback = "Renewal request submitted. Your renewal workflow has been triggered.";
                data.feedbackType = "success";
            }
        }
    }

    var nowMs = new GlideDateTime().getNumericValue();
    var DAY_MS = 86400000;

    function formatDate(value) {
        if (!value) return "";

        var parts = value.substring(0, 10).split("-");
        if (parts.length !== 3) return value;

        var months = [
            "Jan", "Feb", "Mar", "Apr", "May", "Jun",
            "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
        ];

        var month = parseInt(parts[1], 10) - 1;
        var day = parseInt(parts[2], 10);

        if (month < 0 || month > 11) return value;
        return months[month] + " " + day + ", " + parts[0];
    }

    function classifyAsset(type) {
        type = (type || "").toLowerCase();

        if (type.indexOf("textbook") > -1 ||
            type.indexOf("book") > -1) return "book";

        if (type.indexOf("laptop") > -1 ||
            type.indexOf("computer") > -1) return "laptop";

        if (type.indexOf("kit") > -1 ||
            type.indexOf("equipment") > -1) return "kit";

        return "other";
    }

    var gr = new GlideRecord("u_student_rental");
    gr.addQuery("u_student", userId);
    gr.orderByDesc("u_rental_date");
    gr.query();

    while (gr.next()) {
        var statusValue = (gr.getValue("u_status") || "").toLowerCase();
        var isActive = statusValue === "active";
        var isReturned = statusValue === "returned";

        var dueValue = gr.getValue("u_due_date");
        var dueMs = null;
        var daysLeft = null;

        if (dueValue) {
            dueMs = new GlideDateTime(dueValue).getNumericValue();
            daysLeft = Math.ceil((dueMs - nowMs) / DAY_MS);
        }

        var statusLabel = gr.getDisplayValue("u_status") || "Unknown";
        var statusClass = "active";
        var dueClass = "normal";
        var dueLabel = isReturned ? "RETURN STATUS" : "RETURN DEADLINE";

        if (isReturned) {
            statusClass = "returned";
            dueClass = "returned";
            dueLabel = "RETURNED";
        } else if (isActive && dueMs !== null && dueMs < nowMs) {
            statusClass = "overdue";
            dueClass = "overdue";
            statusLabel = "Overdue";
            dueLabel = "PAST DUE";
        } else if (isActive && daysLeft !== null && daysLeft <= 2) {
            statusClass = "due";
            dueClass = "soon";
            statusLabel = "Due Soon";
            dueLabel = daysLeft === 0 ? "DUE TODAY" : "DUE SOON";
        }

        var assetName = gr.getDisplayValue("u_asset") || "Campus Resource";
        var assetType = "";
        var location = "";

        var asset = gr.u_asset.getRefRecord();
        if (asset && asset.isValidRecord()) {
            assetType = asset.getDisplayValue("u_asset_type") || "";
            location = asset.getDisplayValue("u_location") || "";
        }

        var risk = (gr.getDisplayValue("u_return_risk") || "").toLowerCase();
        var renewalRequested = gr.getValue("u_renewal_requested") == "true";

        data.rentals.push({
            id: gr.getUniqueValue(),
            number: gr.getDisplayValue("u_number"),
            assetName: assetName,
            assetType: assetType,
            location: location,
            art: classifyAsset(assetType),
            statusLabel: statusLabel,
            statusClass: statusClass,
			isOverdue: statusClass === "overdue",
			isDueSoon: statusClass === "due",
            dueLabel: dueLabel,
            dueDate: formatDate(dueValue),
            dueClass: dueClass,
            returnDate: formatDate(gr.getValue("u_return_date")),
            risk: risk,
            renewalRequested: renewalRequested
        });

        if (isActive) {
            data.activeCount++;
            if (dueMs !== null && daysLeft !== null && daysLeft <= 2) {
                data.attentionCount++;
            }
        }
    }

    data.loading = false;
})();
